            backgroundRepeat: "repeat",
            backgroundSize: "250px",
          }}
        />

        <div className="relative z-[2] px-6 pb-16 pt-20 sm:px-12 sm:pb-20 sm:pt-28 lg:px-16 lg:pb-24 lg:pt-32">
          <div className="flex flex-col items-center text-center">
            <span className="text-[13px] tracking-wide text-[#d6a176]">
              Agentic Bookmarks
            </span>

            <h1 className="mt-6 font-elegant text-5xl tracking-tight text-white sm:text-6xl lg:text-[5.5rem] lg:leading-[1]">
              Don't search,
              <br />
              <em>just ask.</em>
            </h1>

            <p className="mx-auto mt-6 max-w-lg text-base leading-relaxed text-[#d6a176]">
              Your bookmarks watch, learn, and find. The first bookmark manager
              that actually works for you - autonomously.
            </p>

            <div className="mt-8 flex flex-wrap items-center justify-center gap-3">
              <LandingAppButton
                className="h-10 rounded-full border border-white/10 bg-white/10 px-6 text-sm font-medium text-white backdrop-blur-sm transition-colors hover:bg-white/20"
                signedOutChildren="Get started free"
