@import "tailwindcss";
@import "@fontsource-variable/geist";
@import "@fontsource/instrument-serif";
@import "@fontsource/instrument-serif/400-italic.css";

@source "./**/*.{ts,tsx}";

@theme {
  --color-ink: #0b0910;
  --color-ink-2: #120e18;
  --color-ink-3: #1a1422;
  --color-cream: #f7f1ea;
  --color-mist: #b9afa8;
  --color-dim: #7f746e;
  --color-ember: #ff7a3d;
  --color-ember-soft: #ffb48f;
  --color-rose: #f5a7b4;
  --color-lilac: #c9b3e8;
  --font-sans: "Geist Variable", ui-sans-serif, system-ui, sans-serif;
  --font-display: "Instrument Serif", Georgia, "Times New Roman", serif;
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
}

:root {
  font-family: var(--font-sans);
  color: var(--color-cream);
  background: var(--color-ink);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  color-scheme: dark;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 5rem;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background: var(--color-ink);
  overflow-x: hidden;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

:focus-visible {
  outline: 2px solid var(--color-ember-soft);
  outline-offset: 3px;
  border-radius: 4px;
}

::selection {
  background: rgba(255, 122, 61, 0.35);
  color: var(--color-cream);
}

.font-display {
  font-family: var(--font-display);
  font-weight: 400;
  letter-spacing: -0.01em;
}

/* Film grain overlay for the whole page */
.landing-page {
  position: relative;
  background: var(--color-ink);
  color: var(--color-cream);
}

.landing-page::before {
  position: fixed;
  z-index: 40;
  inset: 0;
  pointer-events: none;
  content: "";
  opacity: 0.05;
  mix-blend-mode: soft-light;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E");
  background-repeat: repeat;
  background-size: 256px 256px;
}

/* Section shells */
.section-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  font-size: 0.75rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--color-ember-soft);
}

.section-eyebrow::before {
  content: "";
  width: 1.5rem;
  height: 1px;
  background: currentColor;
  opacity: 0.7;
}

.glass {
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.hairline {
  border-color: rgba(255, 255, 255, 0.08);
}

/* Scroll reveal */
[data-reveal] {
  opacity: 0;
  transform: translate3d(0, 24px, 0);
  transition:
    opacity 0.9s var(--ease-out-expo),
    transform 0.9s var(--ease-out-expo);
  transition-delay: var(--reveal-delay, 0ms);
  will-change: opacity, transform;
}

[data-reveal="left"] {
  transform: translate3d(-28px, 0, 0);
}

[data-reveal="scale"] {
  transform: scale(0.96);
}

[data-reveal].is-visible {
  opacity: 1;
  transform: none;
}

/* Marquee ticker */
.ticker {
  display: flex;
  width: max-content;
  animation: ticker 42s linear infinite;
}

.ticker-mask {
  mask-image: linear-gradient(
    to right,
    transparent,
    black 12%,
    black 88%,
    transparent
  );
}

@keyframes ticker {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}

/* Slow ambient drift for hero imagery */
@keyframes drift {
  0% {
    transform: scale(1.06) translate3d(0, 0, 0);
  }
  100% {
    transform: scale(1.12) translate3d(-1.5%, -1%, 0);
  }
}

.drift {
  animation: drift 28s ease-in-out infinite alternate;
  will-change: transform;
}

@keyframes pulse-ring {
  0% {
    transform: scale(0.9);
    opacity: 0.8;
  }
  100% {
    transform: scale(1.8);
    opacity: 0;
  }
}

.pulse-ring::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  border: 1px solid currentColor;
  animation: pulse-ring 2.2s ease-out infinite;
}

@keyframes shimmer {
  to {
    background-position: 200% center;
  }
}

.shimmer-text {
  background: linear-gradient(
    100deg,
    var(--color-cream) 0%,
    var(--color-ember-soft) 40%,
    var(--color-cream) 60%
  );
  background-size: 200% auto;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: shimmer 6s linear infinite;
}

/* Image knocked out through the big 100% */
.image-text {
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
